72	    pub(crate) fn new(
73	        handle: AnyWindowHandle,
74	        params: WindowParams,
75	        platform: Weak<TestPlatform>,
76	        display: Rc<dyn PlatformDisplay>,
77	        renderer: Option<Box<dyn PlatformHeadlessRenderer>>,
