80	            Some(r) => r.sprite_atlas(),
81	            None => Arc::new(TestAtlas::new()),
82	        };
83	        Self(Rc::new(Mutex::new(TestWindowState {
84	            bounds: params.bounds,
85	            display,
86	            platform,
87	            handle,
88	            sprite_atlas,
89	            renderer,
