110	        })))
111	    }
112	    pub fn simulate_scheduled_frame(&self) -> bool {
113	        let callback = {
114	            let mut state = self.0.lock();
115	            if !std::mem::take(&mut state.frame_scheduled) {
116	                return false;
117	            }
118	            state.frame_callback_pending = false;
119	            state.request_frame_callback.take()
120	        };
121	        let Some(mut callback) = callback else {
122	            self.0.lock().frame_scheduled = true;
123	            return false;
124	        };
125	
126	        callback(RequestFrameOptions::default());
127	        self.0.lock().request_frame_callback = Some(callback);
128	        true
129	    }
