135	    pub fn simulate_resize(&mut self, size: Size<Pixels>) {
136	        let scale_factor = self.scale_factor();
137	        let mut lock = self.0.lock();
138	        // Always update bounds, even if no callback is registered
139	        lock.bounds.size = size;
140	        let Some(mut callback) = lock.resize_callback.take() else {
141	            return;
142	        };
143	        drop(lock);
144	        callback(size, scale_factor);
145	        self.0.lock().resize_callback = Some(callback);
146	    }
