148	    pub(crate) fn simulate_active_status_change(&self, active: bool) {
149	        let mut lock = self.0.lock();
150	        let Some(mut callback) = lock.active_status_change_callback.take() else {
151	            return;
152	        };
153	        drop(lock);
154	        callback(active);
155	        self.0.lock().active_status_change_callback = Some(callback);
156	    }
