160	        lock.appearance = appearance;
161	        let Some(mut callback) = lock.appearance_change_callback.take() else {
162	            return;
163	        };
164	        drop(lock);
165	        callback();
166	        self.0.lock().appearance_change_callback = Some(callback);
167	    }
