491	            return Ok(None);
492	        };
493	
494	        let mut state = self.0.lock();
495	        state.next_id += 1;
496	        let texture_id = state.next_id;
497	        state.next_id += 1;
498	        let tile_id = state.next_id;
499	
500	        state.tiles.insert(
501	            key.clone(),
502	            crate::AtlasTile {
